#!/usr/bin/env python3
"""external-data-in-containers.py <seed>: external data of the wrong type goes into an array, Map or Set with inferred element types.
The seed picks the way in and the kind of data: an even seed a string where a number is declared, an odd seed a number where a string is declared. Each program takes it out again in every way and uses it. The program type-checks: with // @ts-nocheck nothing would be asserted.
As plain Bun, line by line: an inferred type over external data is a prediction, so nothing may throw that plain Bun does not throw."""
import sys
seed = int(sys.argv[1]); f = "ns"[seed % 2]
GOOD = {"n": "1", "s": "'z'"}[f]; T = {"n": "number", "s": "string"}[f]
X = "data." + f
MAKE = [("literal", "const c = [X];"), ("literal after a good one", "const c = [GOOD, X];"), ("push", "const c = [GOOD]; c.push(X);"), ("push on empty", "const c = []; c.push(X);"), ("unshift", "const c = [GOOD]; c.unshift(X);"), ("splice in", "const c = [GOOD]; c.splice(0, 0, X);"), ("fill", "const c = [GOOD, GOOD]; c.fill(X);"), ("index store", "const c = [GOOD]; c[0] = X;"), ("index store beyond", "const c = [GOOD]; c[1] = X;"),
        ("concat", "const c = [GOOD].concat([X]);"), ("concat of the value", "const c = [GOOD].concat(X);"), ("Array.of", "const c = Array.of(GOOD, X);"), ("Array.from", "const c = Array.from([X]);"), ("new Array", "const c = new Array(GOOD, X);"), ("spread copy", "const b = [X]; const c = [...b];"), ("spread with more", "const b = [X]; const c = [GOOD, ...b, GOOD];"), ("slice copy", "const b = [X]; const c = b.slice();"), ("alias", "const b = [X]; const c = b;"),
        ("returned", "const make = () => [X]; const c = make();"), ("through a let", "let c = [GOOD]; c = [X];"), ("in a literal property", "const o = { list: [X] }; const c = o.list;"), ("in a class field", "class K { list = [X]; } const c = new K().list;"), ("pushed in a helper", "const c = [GOOD]; const add = (l: typeof c) => { l.push(X); }; add(c);"), ("map of a good array", "const c = [GOOD].map(() => X);"), ("from Set", "const s = new Set([GOOD]); s.add(X); const c = [...s];"), ("from Map values", "const m = new Map([[1, GOOD]]); m.set(2, X); const c = [...m.values()];"), ("from Map keys", "const m = new Map([[GOOD, 1]]); m.set(X, 2); const c = Array.from(m.keys());"),
        ("nested", "const outer = [[X]]; const c = outer[0];"), ("conditional", "const c = hide(true) ? [X] : [GOOD];"), ("destructured default", "const [c = [GOOD]] = [[X]];")]
TAKE = [("last index", "c[c.length - 1]"), ("at", "c.at(-1)!"), ("pop", "c.pop()!"), ("shift after reverse", "c.reverse().shift()!"), ("find", "c.find(v => v === X)!"), ("findLast", "c.findLast(() => true)!"), ("for of", "(() => { let r = GOOD; for (const v of c) r = v; return r; })()"), ("for index", "(() => { let r = GOOD; for (let i = 0; i < c.length; i++) r = c[i]; return r; })()"), ("for in", "(() => { let r = GOOD; for (const k in c) r = c[k]; return r; })()"), ("forEach", "(() => { let r = GOOD; c.forEach(v => { r = v; }); return r; })()"),
        ("map", "c.map(v => v)[c.length - 1]"), ("filter", "c.filter(v => v === X)[0]"), ("reduce", "c.reduce((a, v) => v)"), ("reduce with a start", "c.reduce((a, v) => v, GOOD)"), ("reduceRight", "c.reduceRight((a, v) => a)"), ("flat", "[c].flat()[c.length - 1]"), ("flatMap", "c.flatMap(v => [v]).at(-1)!"), ("slice", "c.slice(-1)[0]"), ("splice out", "c.splice(c.length - 1, 1)[0]"), ("toSorted", "c.toSorted(() => 0).at(-1)!"), ("toReversed", "c.toReversed()[0]"), ("with", "c.with(0, c.at(-1)!)[0]"), ("toSpliced", "c.toSpliced(0, 0).at(-1)!"),
        ("destructured", "(() => { const [...all] = c; return all[all.length - 1]; })()"), ("destructured first of reversed", "(() => { const [first] = c.toReversed(); return first; })()"), ("entries", "[...c.entries()].at(-1)![1]"), ("values", "[...c.values()].at(-1)!"), ("iterator by hand", "(() => { let r = GOOD; const it = c[Symbol.iterator](); for (let s = it.next(); !s.done; s = it.next()) r = s.value; return r; })()"), ("Array.from", "Array.from(c).at(-1)!"), ("Array.from with a function", "Array.from(c, v => v).at(-1)!"), ("Object.values", "Object.values(c).at(-1)!"), 
        ("into a Set and out", "[...new Set(c)].at(-1)!"), ("into a Map and out", "new Map(c.map((v, i) => [i, v] as const)).get(c.length - 1)!"), ("some", "(() => { let r = GOOD; c.some(v => { r = v; return false; }); return r; })()"), ("every", "(() => { let r = GOOD; c.every(v => { r = v; return true; }); return r; })()"), ("sort comparator", "(() => { let r = c.at(-1)!; [...c, ...c].sort((a, b) => { r = b; return 0; }); return r === X || r === GOOD ? X : r; })()"), ("findIndex then index", "c[c.findIndex(v => v === X)]"), ("indexOf then index", "c[c.indexOf(X)]"),  ("structuredClone", "structuredClone(c).at(-1)!")]
USE = [("+ 1", "V + 1"), ("1 +", "1 + V"), ("typeof", "typeof V"), ("template", "`<${V}>`"), ("=== itself", "V === X"), ("truthiness", "V ? 'yes' : 'no'"), ("+= on a let", "(() => { let n = GOOD; n += V; return n; })()"), ("String", "String(V)"), ("?? and +", "(V ?? GOOD) + 1"), ("as an argument", "((p = GOOD) => p + 1)(V)"), ("stored and read", "(() => { let n = GOOD; n = V; return n + 1; })()")]
if f == "n": USE += [("* 2", "V * 2"), ("negated", "-V"), ("compared", "V < 5"), ("into a let and incremented", "(() => { let n = GOOD; n = V; n++; return n; })()"), ("Math.max", "Math.max(V, 0)"), ("| 0", "V | 0")]
else: USE += [(".length", "V.length"), ("compared", "V < 'm'"), ("concat twice", "V + V")]
out = ["declare const console: { log(text: string): void }; declare function structuredClone<T>(value: T): T;", "const data = JSON.parse('{\"n\":\"abc\",\"s\":5}') as { n: number; s: string };", "const boxes: unknown[] = []; const hide = <T,>(x: T): T => { boxes.push(x); return boxes.pop() as T; };",
       "const show = (v: unknown): string => v === undefined ? '<undefined>' : v === null ? '<null>' : typeof v === 'number' ? (Object.is(v, -0) ? '<-0>' : String(v)) : typeof v === 'string' ? JSON.stringify(v) : String(v);",
       "const say = (label: string, f: () => unknown): void => { let r: string; try { r = show(f()); } catch (e) { r = 'throws ' + (e as Error).constructor.name + (String((e as Error).message).includes('(bun compile') ? ' by the compiler' : ''); } console.log(label + ' ==> ' + r); };"]
k = 0
i = seed // 2; mt, m = MAKE[i]
if True:
    for j, (tt, t) in enumerate(TAKE):
        ut, u = USE[(i * len(TAKE) + j) % len(USE)]; ut2, u2 = USE[(i * len(TAKE) + j + 5) % len(USE)]
        for name, use in ((ut, u), (ut2, u2)):
            k += 1
            body = "%s const taken = %s; return %s;" % (m, t, use.replace("V", "taken")) if k % 2 else "%s return %s;" % (m, use.replace("V", "(" + t + ")"))
            out.append("function f%d() { %s } say(%r, f%d);" % (k, body.replace("GOOD", GOOD).replace("TYPE", T).replace("X", X), "%s | %s | %s" % (mt, tt, name), k))
print("\n".join(out))
